using System;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Animations;using UnityEngine.Playables;
[DefaultExecutionOrder(2200)]public sealed class Hair210R2View:MonoBehaviour{
 public Eye206R2View source;public Mesh baselineMesh,candidateMesh;public Hair208View crop;public float sourceFrame;public float phaseX,phaseY;public bool candidate,playing;public float speed=.25f;public Vector3 rootRest;public int renderedFrame=-1;public bool renderedCandidate;public float renderedSourceFrame;PlayableGraph graph;AnimationClipPlayable clip;float elapsed;RenderPipelineAsset oldG,oldQ;bool started;
 public void SetState(float f,float x,float y,bool b){sourceFrame=f;phaseX=x;phaseY=y;candidate=b;var a=source.motion.target;if(!graph.IsValid()){source.motion.Release();a.enabled=true;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;graph=PlayableGraph.Create("H210 same existing walk only");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);clip=AnimationClipPlayable.Create(graph,source.motion.existingWalk);clip.SetApplyFootIK(false);clip.SetApplyPlayableIK(false);clip.SetSpeed(0);var o=AnimationPlayableOutput.Create(graph,"H210 sameHumanoid",a);o.SetSourcePlayable(clip);graph.Play();}a.transform.position=rootRest;clip.SetTime(source.motion.existingWalk.length*(f/40f));graph.Evaluate(0);var cam=source.Layers.game.actor.inheritedView.worldCamera;a.transform.position=rootRest+cam.transform.right*(x/source.Layers.game.ppu)-cam.transform.up*(y/source.Layers.game.ppu);source.Layers.game.actor.ownedUV1Mesh=b?candidateMesh:baselineMesh;source.Layers.game.actor.Apply();}
 void Start(){oldG=GraphicsSettings.defaultRenderPipeline;oldQ=QualitySettings.renderPipeline;GraphicsSettings.defaultRenderPipeline=QualitySettings.renderPipeline=source.Layers.pipeline;Shader.SetGlobalFloat("_FHEnabled44",0);Shader.SetGlobalFloat("_E189Diag",0);Shader.SetGlobalFloat("_E189FieldEnabled",0);Shader.SetGlobalFloat("_E202MainHideEyes",0);Eye202Layers.Current=source.Layers;Eye206R2Layers.Current=source;source.Layers.game.SetPose(0);source.Layers.game.Bind(true);Hair208Layers.Current=crop;SetState(sourceFrame,phaseX,phaseY,candidate);Hair210R2Stage.Install(this);started=true;}
 void Update(){if(playing){elapsed+=Time.unscaledDeltaTime*speed;float dt=source.motion.existingWalk.length/40;if(elapsed>=dt){int n=Mathf.FloorToInt(elapsed/dt);elapsed-=n*dt;SetState((Mathf.FloorToInt(sourceFrame)+n)%40,0,0,candidate);}}}
 public void NativeRender(){source.Render(true);renderedFrame=Time.frameCount;renderedCandidate=candidate;renderedSourceFrame=sourceFrame;}
 void OnGUI(){GUI.Label(new Rect(10,8,1050,45),"H210 single source contour / "+(renderedCandidate?"B authored hair (unadopted)":"A unchanged B14 hair")+" / source frame "+renderedSourceFrame.ToString("F3")+"\n480x272 same game camera/PPU90.50967; 130px rest reference, natural walk height; centre sample (.75,.25). Art HOLD.");if(GUI.Button(new Rect(10,56,100,25),candidate?"Show A":"Show B")){playing=false;SetState(sourceFrame,phaseX,phaseY,!candidate);}if(GUI.Button(new Rect(120,56,80,25),playing?"Pause":"Play"))playing=!playing;if(GUI.Button(new Rect(210,56,65,25),"0.25x"))speed=.25f;if(GUI.Button(new Rect(285,56,55,25),"1x"))speed=1;if(GUI.Button(new Rect(350,56,45,25),"<")){playing=false;SetState(Mathf.Max(0,Mathf.Floor(sourceFrame)-1),0,0,candidate);}if(GUI.Button(new Rect(405,56,45,25),">")){playing=false;SetState(Mathf.Min(40,Mathf.Floor(sourceFrame)+1),0,0,candidate);}if(source.Colour){GUI.DrawTexture(new Rect(10,94,480,272),source.Colour,ScaleMode.StretchToFill,false);GUI.DrawTextureWithTexCoords(new Rect(510,94,411,468),source.Colour,new Rect(150/480f,(272-210)/272f,137/480f,156/272f),false);GUI.DrawTextureWithTexCoords(new Rect(10,388,200,192),source.Colour,new Rect(206/480f,(272-97)/272f,25/480f,24/272f),false);}}
 void OnDisable(){Hair210R2Stage.Remove(this);if(graph.IsValid())graph.Destroy();Hair208Layers.DisposeBuffers();Hair208Layers.Current=null;Eye206R2Layers.Dispose();Eye202Layers.Dispose();if(started){GraphicsSettings.defaultRenderPipeline=oldG;QualitySettings.renderPipeline=oldQ;started=false;}}
